import{z as A,x as i,o as t,c as B,q as d,j as o,D as E,d as l,s as r,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"长卷积","description":"","frontmatter":{"title":"长卷积","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/long-convolution.md","filePath":"llm/long-convolution.md","lastUpdated":1791413859000}'),p={name:"llm/long-convolution.md"};function F(m,a,u,h,S,T){const n=i("Mermaid");return t(),B("div",null,[a[2]||(a[2]=d('<h1 id="长卷积" tabindex="-1">长卷积 <a class="header-anchor" href="#长卷积" aria-label="Permalink to &quot;长卷积&quot;">​</a></h1><div class="epigraph"><p>用覆盖整个上下文的卷积核代替逐步状态；训练是 FFT 卷积，参数是滤波器而不是随时间改写的权重。</p><footer>—— Poli et al., Hyena Hierarchy, 2023；连续核的前身见 Romero et al., CKConv, NeurIPS 2021</footer></div><p><a href="/llm/ttt-layers">上一课</a>每步改内环权重。<a href="/llm/hippo-s4">S4</a> 已经说明时不变 SSM <strong>等价于</strong>一条长卷积核。本课把卷积本身当设计对象：核由隐式 MLP 生成（CKConv / Hyena），或由 SSM 展开，强调<strong>无选择性、无测试时更新</strong>时还能做什么。后课混合比要决定哪些层用卷积/SSM、哪些层用注意力；本课先给卷积槽位一个干净定义。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>逐步扫描、TTT、delta 都维护随 \\(t\\) 变化的状态。时不变长卷积问的是反面：若核 \\(k_{1:n}\\) 在整段上固定（或只随相对位移变），一条 FFT 卷积 \\(y=k*x\\) 能否承担中远程混合，把二次注意力留给少数层？缺口是核怎么参数化才既长又稳：直接学 \\(n\\) 个抽头，长度一变就失效；隐式核用位置 \\(t\\) 的函数 \\(k(t)\\)，长度外推更自然。</p><p>Hyena 把这种长核叠成层级，中间插入元素级门，接近「用卷积搭一条表达力更强的 S4」。选择仍弱于 Mamba，因为核不随内容改形状，只靠门调制输入。</p><p><span class="marginnote">短卷积（多 token 注意力里宽度 3、5）是局部归纳。本课的核长度与上下文同阶，对象不同。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>隐式核：\\(k_t=\\mathrm{MLP}(\\psi(t))\\)，\\(\\psi\\) 为位置特征（指数衰减窗口、正弦等）。窗口保证远端衰减，避免核在远距仍有大能量导致不稳定。前向用 FFT 卷积，复杂度 \\(\\Theta(n\\log n)\\)，优于朴素 \\(\\Theta(n^2)\\)，弱于逐步线性里极小常数的扫描——但实现成熟、无递归数值链。<span class="marginnote">术语翻译：卷积就是「滑动加权平均」——拿一条固定的权重条在序列上滑，滑到哪就给邻域加个权。直接算是 \\(n^2\\) 次乘法；FFT（快速傅里叶变换）把两列数转到频域做逐点相乘再转回来，只要约 \\(n\\log n\\) 次——\\(n=10^5\\) 时大约是 100 亿次对 170 万次的差别。</span></p><p>层级：若干长卷积与门控交替，感受野迅速覆盖全文。因果靠核的负位移为零或用因果 FFT 技巧。与 SSM 的关系：若 \\(k_t=C A^{t} B\\)，则退回 S4；Hyena 的 MLP 核更自由，不一定对应低维状态，推理就不能改成常数状态循环，除非再做有理逼近。</p><h3 id="推理接口" tabindex="-1">推理接口 <a class="header-anchor" href="#推理接口" aria-label="Permalink to &quot;推理接口&quot;">​</a></h3><p>FFT 卷积在自回归解码时不友好：每步扩展序列要重做或用增量滤波。若核来自 SSM，应改回循环。若核是自由 MLP，解码要么缓存卷积状态（等价 FIR 滤波器，状态长度等于核长，可能很长），要么放弃该层用于生成主干。这是长卷积进 LLM 的硬边界。<span class="marginnote">数字实例：核长 64k、通道 1024 时，FIR 状态要缓存最近 \\(64\\text{k}\\times1024\\) 个数，fp16 下约 128 MB——而且随上下文长度同阶增长，把「线性复杂度」的卖点在显存上又还了回去。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>时不变核实现的是与内容无关的混合：位置 \\(t\\) 对 \\(t-\\delta\\) 的权重只看 \\(\\delta\\)。门控（输入逐点乘）注入内容，使「这一层要不要启用卷积通道」可学，但不改核形状。因此长卷积擅长平滑、局部到中程的模式、声学与时间序列；不擅长「在不确定距离上找那个唯一的变量名」。<span class="marginnote">直觉类比：时不变核像一把齿距固定的梳子，梳到哪段内容、齿距都一样；注意力更像一根会先看内容再落点的手指。梳子擅长抚平整段纹理，找「第 317 行那个词」这种事只能靠会看的指头。</span></p><p>训练快、生成难，是同一枚硬币的两面：</p>',15)),(t(),o(s,null,{default:E(()=>[r(n,{id:"mermaid-43",class:"mermaid",graph:"flowchart%20TD%0A%20%20TR%5B%22%E8%AE%AD%E7%BB%83%3A%20%E6%95%B4%E6%AE%B5%E5%B9%B6%E8%A1%8C%22%5D%20--%3E%20FFT%5B%22%E4%B8%80%E6%AC%A1%E5%9B%A0%E6%9E%9C%20FFT%20%E5%8D%B7%E7%A7%AF%3Cbr%2F%3E%CE%98(n%20log%20n)%2C%20%E5%85%A8%E6%AE%B5%E4%B8%80%E8%B5%B7%E7%AE%97%22%5D%0A%20%20GEN%5B%22%E7%94%9F%E6%88%90%3A%20%E4%B8%80%E6%AC%A1%E5%90%90%E4%B8%80%E4%B8%AA%20token%22%5D%20--%3E%20ST%5B%22%E6%AF%8F%E6%AD%A5%E9%83%BD%E8%A6%81%E3%80%8E%E5%88%B0%E6%AD%A4%E4%B8%BA%E6%AD%A2%E3%80%8F%E7%9A%84%E7%8A%B6%E6%80%81%22%5D%0A%20%20ST%20--%3E%20FIR%5B%22%E8%87%AA%E7%94%B1%20MLP%20%E6%A0%B8%3A%20%E7%8A%B6%E6%80%81%20%3D%20%E6%9C%80%E8%BF%91%E6%A0%B8%E9%95%BF%E4%B8%AA%E8%BE%93%E5%85%A5%3Cbr%2F%3E%E5%8F%AF%E8%83%BD%E5%B7%A8%E5%A4%A7%22%5D%0A%20%20SSM%5B%22%E6%A0%B8%E5%8F%AF%E5%86%99%E6%88%90%20A%5Et%20(SSM%20%E5%BD%A2%E5%BC%8F)%22%5D%20--%3E%20LOOP%5B%22%E6%94%B9%E5%9B%9E%E5%B8%B8%E6%95%B0%E7%8A%B6%E6%80%81%E5%BE%AA%E7%8E%AF%3Cbr%2F%3E%E9%97%AE%E9%A2%98%E6%B6%88%E5%A4%B1%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"\\(\\Theta(n\\log n)\\) 在中等 \\(n\\) 上常快于尚未融合的扫描；极大 \\(n\\) 上线性扫描常数更重要。课序比较的是归纳偏置，不单比渐近符号。",-1)),a[4]||(a[4]=e("p",null,[e("span",{class:"marginnote"},"自由长核没有低维状态，SSD 对偶不自动成立。不要把 Hyena 层塞进 Mamba-2 核。")],-1)),a[5]||(a[5]=e("h2",{id:"边界",tabindex:"-1"},[l("边界 "),e("a",{class:"header-anchor",href:"#边界","aria-label":'Permalink to "边界"'},"​")],-1)),a[6]||(a[6]=e("p",null,"生成解码是长卷积的弱项，除非核有 SSM 实现。选择性缺席，召回基准通常差。下一课不会再展开新的线性算子，而是问一层注意力掺几层这类线性模块——混合比。把全部层换成 Hyena 再指望精确拷贝，会被后课的召回瓶颈打脸。",-1)),(t(),o(s,null,{default:E(()=>[r(n,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E7%9B%B8%E5%AF%B9%E4%BD%8D%E7%BD%AE%20t%22%5D%20--%3E%20MLP%5B%22%E9%9A%90%E5%BC%8F%20MLP%20%E7%94%9F%E6%88%90%E6%A0%B8%22%5D%0A%20%20MLP%20--%3E%20FFT%5B%22%E5%9B%A0%E6%9E%9C%20FFT%20%E5%8D%B7%E7%A7%AF%22%5D%0A%20%20X%5B%22%E8%BE%93%E5%85%A5%22%5D%20--%3E%20Gate%5B%22%E5%85%83%E7%B4%A0%E9%97%A8%22%5D%0A%20%20Gate%20--%3E%20FFT%0A%20%20FFT%20--%3E%20Y%5B%22%E8%BE%93%E5%87%BA%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=e("h2",{id:"小结",tabindex:"-1"},[l("小结 "),e("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[8]||(a[8]=e("ul",null,[e("li",null,"长卷积用与上下文同阶的核做时不变混合，隐式 MLP 生成核以便外推。"),e("li",null,"训练常用 FFT，\\(\\Theta(n\\log n)\\)；若核无低维 SSM 实现，自回归状态可能长达核长。"),e("li",null,"门改输入不改核形状，选择性弱于 Mamba。"),e("li",null,"与宽度为个位数的局部卷积不是同一课。"),e("li",null,"出处：Poli et al., 2023；Romero et al., NeurIPS 2021。")],-1))])}const M=A(p,[["render",F]]);export{f as __pageData,M as default};
